-- Catálogo de la imagen del usuario. Pagos y capitalización mensuales.
-- No modifica solicitudes ni contratos ya pactados.
SET NAMES utf8mb4;
START TRANSACTION;
SET @mensual=(SELECT Id FROM Periodicidades WHERE Unidad='MESES' AND Intervalo=1 AND PeriodosPorAnio=12 AND Activo=1 LIMIT 1);
SET @producto=(SELECT Id FROM ProductosFinancieros WHERE Codigo='PRE-01' OR Nombre='Préstamo Personal' ORDER BY Id LIMIT 1);
INSERT INTO ProductosFinancieros(Codigo,Nombre,Descripcion,MontoMinimo,MontoMaximo,PlazoMinimo,PlazoMaximo,PlazoMinimoMeses,PlazoMaximoMeses,TipoComision,ValorComision,TipoGastos,ValorGastos,Activo) SELECT 'PRE-01','Préstamo Personal','Consumo personal de libre destino',500,15000,6,60,6,60,'PORCENTAJE',2,'FIJO',0,1 WHERE @producto IS NULL;
SET @producto=COALESCE(@producto,(SELECT Id FROM ProductosFinancieros WHERE Codigo='PRE-01'));
UPDATE ProductosFinancieros SET Nombre='Préstamo Personal',Descripcion='Consumo personal de libre destino',MontoMinimo=500,MontoMaximo=15000,PlazoMinimo=6,PlazoMaximo=60,PlazoMinimoMeses=6,PlazoMaximoMeses=60,TipoComision='PORCENTAJE',ValorComision=2,TipoGastos='FIJO',ValorGastos=0,Activo=1 WHERE Id=@producto;
DELETE pm FROM ProductoMetodos pm JOIN MetodosCalculo m ON m.Id=pm.MetodoId WHERE pm.ProductoId=@producto AND m.Codigo NOT IN ('FRANCES','ALEMAN') AND NOT EXISTS(SELECT 1 FROM Solicitudes s WHERE s.ProductoId=pm.ProductoId AND s.MetodoId=pm.MetodoId) AND NOT EXISTS(SELECT 1 FROM Prestamos p WHERE p.ProductoId=pm.ProductoId AND p.MetodoId=pm.MetodoId);
INSERT IGNORE INTO ProductoMetodos(ProductoId,MetodoId) SELECT @producto,Id FROM MetodosCalculo WHERE Codigo IN ('FRANCES','ALEMAN');
INSERT IGNORE INTO ProductoPeriodicidades(ProductoId,PeriodicidadId) VALUES(@producto,@mensual);
DELETE pp FROM ProductoPeriodicidades pp WHERE pp.ProductoId=@producto AND pp.PeriodicidadId<>@mensual AND NOT EXISTS(SELECT 1 FROM Solicitudes s WHERE s.ProductoId=pp.ProductoId AND s.PeriodicidadId=pp.PeriodicidadId) AND NOT EXISTS(SELECT 1 FROM Prestamos p WHERE p.ProductoId=pp.ProductoId AND p.PeriodicidadId=pp.PeriodicidadId);
SET @tasa=(SELECT Id FROM Tasas WHERE ProductoId=@producto AND Porcentaje=12 AND TipoTasa='NOMINAL_ANUAL' AND CapitalizacionId=@mensual AND Activo=1 AND VigenteDesde<='2026-10-30' AND (VigenteHasta IS NULL OR VigenteHasta>='2026-10-30') ORDER BY Id DESC LIMIT 1);
INSERT INTO Tasas(ProductoId,Porcentaje,TipoTasa,CapitalizacionId,VigenteDesde,Activo,EsPredeterminada) SELECT @producto,12,'NOMINAL_ANUAL',@mensual,'2026-10-30',1,0 WHERE @tasa IS NULL;
SET @tasa=IF(@tasa IS NULL,LAST_INSERT_ID(),@tasa);
UPDATE Tasas SET EsPredeterminada=(Id=@tasa) WHERE ProductoId=@producto;
SET @producto=(SELECT Id FROM ProductosFinancieros WHERE Codigo='PRE-AUTO' OR Nombre='Préstamo Auto' ORDER BY Id LIMIT 1);
INSERT INTO ProductosFinancieros(Codigo,Nombre,Descripcion,MontoMinimo,MontoMaximo,PlazoMinimo,PlazoMaximo,PlazoMinimoMeses,PlazoMaximoMeses,TipoComision,ValorComision,TipoGastos,ValorGastos,Activo) SELECT 'PRE-AUTO','Préstamo Auto','Vehículos nuevos y seminuevos',5000,40000,12,84,12,84,'PORCENTAJE',1.5,'FIJO',0,1 WHERE @producto IS NULL;
SET @producto=COALESCE(@producto,(SELECT Id FROM ProductosFinancieros WHERE Codigo='PRE-AUTO'));
UPDATE ProductosFinancieros SET Nombre='Préstamo Auto',Descripcion='Vehículos nuevos y seminuevos',MontoMinimo=5000,MontoMaximo=40000,PlazoMinimo=12,PlazoMaximo=84,PlazoMinimoMeses=12,PlazoMaximoMeses=84,TipoComision='PORCENTAJE',ValorComision=1.5,TipoGastos='FIJO',ValorGastos=0,Activo=1 WHERE Id=@producto;
DELETE pm FROM ProductoMetodos pm JOIN MetodosCalculo m ON m.Id=pm.MetodoId WHERE pm.ProductoId=@producto AND m.Codigo NOT IN ('FRANCES') AND NOT EXISTS(SELECT 1 FROM Solicitudes s WHERE s.ProductoId=pm.ProductoId AND s.MetodoId=pm.MetodoId) AND NOT EXISTS(SELECT 1 FROM Prestamos p WHERE p.ProductoId=pm.ProductoId AND p.MetodoId=pm.MetodoId);
