INSERT IGNORE INTO ProductoPeriodicidades(ProductoId,PeriodicidadId) VALUES(@producto,@mensual);
DELETE pp FROM ProductoPeriodicidades pp WHERE pp.ProductoId=@producto AND pp.PeriodicidadId<>@mensual AND NOT EXISTS(SELECT 1 FROM Solicitudes s WHERE s.ProductoId=pp.ProductoId AND s.PeriodicidadId=pp.PeriodicidadId) AND NOT EXISTS(SELECT 1 FROM Prestamos p WHERE p.ProductoId=pp.ProductoId AND p.PeriodicidadId=pp.PeriodicidadId);
SET @tasa=(SELECT Id FROM Tasas WHERE ProductoId=@producto AND Porcentaje=9.5 AND TipoTasa='EFECTIVA_ANUAL' AND CapitalizacionId=@mensual AND Activo=1 AND VigenteDesde<='2026-10-30' AND (VigenteHasta IS NULL OR VigenteHasta>='2026-10-30') ORDER BY Id DESC LIMIT 1);
INSERT INTO Tasas(ProductoId,Porcentaje,TipoTasa,CapitalizacionId,VigenteDesde,Activo,EsPredeterminada) SELECT @producto,9.5,'EFECTIVA_ANUAL',@mensual,'2026-10-30',1,0 WHERE @tasa IS NULL;
SET @tasa=IF(@tasa IS NULL,LAST_INSERT_ID(),@tasa);
UPDATE Tasas SET EsPredeterminada=(Id=@tasa) WHERE ProductoId=@producto;
SET @producto=(SELECT Id FROM ProductosFinancieros WHERE Codigo='MICRO' OR Nombre='Microcrédito' ORDER BY Id LIMIT 1);
INSERT INTO ProductosFinancieros(Codigo,Nombre,Descripcion,MontoMinimo,MontoMaximo,PlazoMinimo,PlazoMaximo,PlazoMinimoMeses,PlazoMaximoMeses,TipoComision,ValorComision,TipoGastos,ValorGastos,Activo) SELECT 'MICRO','Microcrédito','Capital de trabajo microempresarial',200,3000,3,18,3,18,'FIJO',0,'FIJO',0,1 WHERE @producto IS NULL;
