SET @tasa=(SELECT Id FROM Tasas WHERE ProductoId=@producto AND Porcentaje=18 AND TipoTasa='NOMINAL_ANUAL' AND CapitalizacionId=@mensual AND Activo=1 AND VigenteDesde<='2026-10-30' AND (VigenteHasta IS NULL OR VigenteHasta>='2026-10-30') ORDER BY Id DESC LIMIT 1);
